from collections import deque
H=len(grid);W=len(grid[0]); seen=set(); comps=[]
for r in range(H):
 for c in range(W):
  if grid[r][c] and (r,c) not in seen:
   col=grid[r][c]; q=[(r,c)];seen.add((r,c)); cells=[]
   while q:
    a,b=q.pop();cells.append((a,b))
    for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
     if 0<=x<H and 0<=y<W and grid[x][y]==col and (x,y) not in seen:seen.add((x,y));q.append((x,y))
   comps.append((col,cells))
[(co,len(cs),cs) for co,cs in comps]
